#include "package_test_session.h"
#include <atomic>
#include <mutex>
int main(){try{
 std::atomic<unsigned> checks{0};auto check=[&](bool value,const char *why){if(!value)throw std::runtime_error(why);++checks;};elf_image image{};check(!elf_load(PACKAGE_IMAGE,0x74000000,nullptr,&image),"actual NDK Object constructor fixture loads");Session h(image);
 auto owner=h.find("java/lang/Object"),method=h.method("java/lang/Object","<init>","()V");check(owner&&method&&h.host.PendingException().empty(),"exact public Object constructor resolves");
 auto run=[&](addr_t clazz,addr_t constructor,unsigned mode){struct Guard {uint64_t before=0x1122334455667788ULL,value=0,after=0x8877665544332211ULL;}guard;auto result=h.run("object_construct",{h.host.EnvAddress(),clazz,constructor,mode,reinterpret_cast<addr_t>(&guard.value)});check(guard.before==0x1122334455667788ULL&&guard.after==0x8877665544332211ULL&&guard.value==UINT64_C(0xfedcba9876543210),"zero-argument direct/V/A preserve guest jvalue/output bounds");return result;};
 std::vector<addr_t> live;
 for(unsigned mode=0;mode<4;++mode)for(unsigned repeat=0;repeat<4;++repeat){auto result=run(owner,method,mode);check(result&&h.call(232,result)==1&&h.host.PendingException().empty(),"Object constructor promotes one real caller local");auto clazz=h.run("object_construct_class",{h.host.EnvAddress(),result});check(h.call(24,clazz,owner)&&h.host.ClassNameValue(clazz)==std::optional<std::string>("java/lang/Object"),"fresh object has exact Object class");h.host.DeleteLocalReference(clazz);for(auto earlier:live)check(!h.call(24,earlier,result),"distinct constructor calls allocate distinct identity");live.push_back(result);}
 for(auto result:live){auto weak=h.call(226,result),global=h.host.NewGlobalReference(result),local=h.host.NewLocalReference(result);h.host.DeleteLocalReference(result);check(h.call(24,weak,global)&&h.call(24,local,global),"real global and copied local preserve constructed identity");h.host.DeleteGlobalReference(global);check(!h.call(24,weak,0),"copied local is a real remaining root");h.host.DeleteLocalReference(local);check(h.call(24,weak,0),"constructed Object has no hidden factory-frame root");h.call(227,weak);}
 h.host.DefineClass("ObjectChild");h.host.DefineClass("UnimplementedCtor",{{"<init>","()V"}});h.host.DefineInterface("ObjectInterface",{});
 for(auto name:{"ObjectChild","java/lang/String","ObjectInterface","[Ljava/lang/Object;"})for(unsigned mode=0;mode<4;++mode){auto result=run(h.find(name),method,mode);check(!result&&!h.host.PendingException().empty(),"Object constructor cannot manufacture subclass, string, interface or array instances");h.host.ClearException();}
 for(unsigned mode=0;mode<4;++mode){check(!run(owner,UINT64_C(0x1234567890),mode)&&h.host.PendingException().find("NoSuchMethodError")!=std::string::npos,"invalid constructor ID rejected");h.host.ClearException();check(!run(0,method,mode)&&h.host.PendingException().find("NullPointerException")!=std::string::npos,"null constructor owner rejected");h.host.ClearException();}
 auto unavailable=h.method("UnimplementedCtor","<init>","()V");bool rejected=false;try{h.call(28,h.find("UnimplementedCtor"),unavailable);}catch(const std::runtime_error &error){rejected=std::string(error.what()).find("no host implementation")!=std::string::npos;}check(rejected,"unimplemented subclass constructor remains explicit");
 auto object=h.host.NewInstance("java/lang/Object");check(!h.zero(object,method,0)&&h.host.PendingException().find("IllegalArgumentException")!=std::string::npos,"ordinary method call cannot stand in for constructor invocation");h.host.ClearException();
 auto global_owner=h.host.NewGlobalReference(owner);std::vector<std::thread> workers;std::exception_ptr failure;std::mutex mutex;
 for(unsigned n=0;n<3;++n)workers.emplace_back([&,n]{try{addr_t env=0;State vm{};vm.gpr.x0.qword=h.host.VmAddress();vm.gpr.x1.qword=reinterpret_cast<addr_t>(&env);h.host.InvokeVm(4,vm);check(env!=0,"worker attaches before constructor call");for(unsigned repeat=0;repeat<5;++repeat){auto result=run(global_owner,method,(n+repeat)%4);check(result&&h.call(232,result)==1,"concurrent construction owns a fresh thread-local result");h.host.DeleteLocalReference(result);}vm={};vm.gpr.x0.qword=h.host.VmAddress();h.host.InvokeVm(5,vm);check(static_cast<int32_t>(vm.gpr.x0.qword)==0,"constructor worker detaches after owned frame drains");}catch(...){std::lock_guard lock(mutex);if(!failure)failure=std::current_exception();}});
 for(auto &worker:workers)worker.join();if(failure)std::rethrow_exception(failure);check(h.host.PendingException().empty(),"no hidden Object constructor exception");std::printf("JNI Object constructor: %u checks; actual NDK direct/V/A, exact-owner allocation, identities, local/global/weak lifetime, invalid shapes and concurrent owned frames\n",checks.load());
}catch(const std::exception &error){std::fprintf(stderr,"Object constructor test: %s\n",error.what());return 1;}}
